  3	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
  4	public final class EmailSender {
  5	
  6	    private static final String SIGNATURE = "\n--\nPousada Maré Alta\n(79) 3200-0000 | @pousadamarealta\n";
  7	    private final SentMessages sentMessages;
  8	
  9	    public EmailSender(SentMessages sentMessages) {
 10	        this.sentMessages = sentMessages;
 11	    }
 12	
 13	    public Message send(String to, String subject, String body) {
 14	        return sentMessages.add("EMAIL", to, subject, body + SIGNATURE);
 15	    }
 16	}
