 20	}
 21	package hotel.messages;
 22	
 23	import java.sql.Connection;
 24	import java.sql.PreparedStatement;
 25	import java.sql.ResultSet;
 26	import java.sql.SQLException;
 27	import java.util.ArrayList;
 28	import java.util.List;
 29	import javax.sql.DataSource;
 30	
 31	/** Every message the inn sent, so the front desk can check what each guest received. */
 32	public final class SentMessages {
 33	
 34	    private final DataSource dataSource;
 35	
 36	    public SentMessages(DataSource dataSource) {
 37	        this.dataSource = dataSource;
 38	    }
 39	
 40	    Message add(String channel, String to, String subject, String body) {
 41	        try (Connection connection = dataSource.getConnection();
 42	                PreparedStatement insert = connection.prepareStatement(
 43	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
 44	            insert.setString(1, channel);
 45	            insert.setString(2, to);
 46	            insert.setString(3, subject);
 47	            insert.setString(4, body);
 48	            try (ResultSet generated = insert.executeQuery()) {
 49	                generated.next();
 50	                return new Message(generated.getLong("id"), channel, to, subject, body);
 51	            }
 52	        } catch (SQLException failure) {
 53	            throw new IllegalStateException("could not keep the message to " + to, failure);
 54	        }
 55	    }
 56	
 57	    public List<Message> all() {
 58	        try (Connection connection = dataSource.getConnection();
 59	                PreparedStatement select = connection.prepareStatement(
 60	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
 61	                ResultSet rows = select.executeQuery()) {
 62	            List<Message> messages = new ArrayList<>();
 63	            while (rows.next()) {
 64	                messages.add(new Message(
 65	                        rows.getLong("id"),
 66	                        rows.getString("channel"),
 67	                        rows.getString("recipient"),
 68	                        rows.getString("subject"),
 69	                        rows.getString("body")));
 70	            }
 71	            return messages;
 72	        } catch (SQLException failure) {
 73	            throw new IllegalStateException("could not read the sent messages", failure);
 74	        }
 75	    }
 76	}
 77	package hotel.reservations;
 78	
 79	import hotel.documents.ReservationReceipt;
 80	import hotel.messages.EmailSender;
 81	import hotel.rooms.Room;
 82	import hotel.rooms.Rooms;
 83	import java.math.BigDecimal;
 84	
 85	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 86	public final class ReservationService {
 87	
 88	    static final String HOTEL_NAME = "Pousada Maré Alta";
 89	
 90	    private final Rooms rooms;
 91	    private final ReservationStore store;
 92	    private final PriceCalculator priceCalculator;
 93	    private final EmailSender emailSender;
 94	
 95	    public ReservationService(
 96	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 97	        this.rooms = rooms;
 98	        this.store = store;
 99	        this.priceCalculator = priceCalculator;
100	        this.emailSender = emailSender;
101	    }
102	
103	    public synchronized Reservation create(NewReservation request) {
104	        if (!request.checkOut().isAfter(request.checkIn())) {
105	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
106	        }
107	        if (request.guests() < 1) {
108	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
109	        }
110	        Room room = rooms.find(request.roomNumber())
111	                .orElseThrow(() -> new HotelException(
112	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
113	        if (request.guests() > room.capacity()) {
114	            throw new HotelException(
115	                    ErrorCode.CAPACITY_EXCEEDED,
116	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
117	        }
118	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
119	            throw new HotelException(
120	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
121	        }
122	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
123	        return store.add(request, price);
124	    }
125	
126	    public Reservation find(long reservationId) {
127	        return store.find(reservationId)
128	                .orElseThrow(() -> new HotelException(
129	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
130	    }
131	
132	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
133	    public synchronized Reservation confirm(long reservationId) {
134	        Reservation reservation = find(reservationId);
135	        if (reservation.status() != ReservationStatus.PENDING) {
136	            throw notAllowed(reservation, "confirm");
137	        }
138	        reservation.confirmPayment();
139	        store.update(reservation);
140	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
141	        emailSender.send(
142	                reservation.guest().email(),
143	                "Reserva confirmada - " + HOTEL_NAME,
144	                confirmationEmailBody(reservation, receipt));
145	        return reservation;
146	    }
147	
148	    /**
149	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
150	     * reservation was never paid, so nothing comes back).
151	     */
152	    public synchronized Reservation cancel(long reservationId) {
153	        Reservation reservation = find(reservationId);
154	        if (reservation.status() != ReservationStatus.PENDING
155	                && reservation.status() != ReservationStatus.CONFIRMED) {
156	            throw notAllowed(reservation, "cancel");
157	        }
158	        BigDecimal refund = switch (reservation.ratePlan()) {
159	            case STANDARD -> reservation.amountPaid();
160	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
161	        };
162	        reservation.cancel(refund);
163	        store.update(reservation);
164	        return reservation;
165	    }
166	
167	    public synchronized Reservation checkIn(long reservationId) {
168	        Reservation reservation = find(reservationId);
169	        if (reservation.status() != ReservationStatus.CONFIRMED) {
170	            throw notAllowed(reservation, "check in");
171	        }
172	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
173	        store.update(reservation);
174	        return reservation;
175	    }
176	
177	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
178	    public synchronized ReservationReceipt checkOut(long reservationId) {
179	        Reservation reservation = find(reservationId);
180	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
181	            throw notAllowed(reservation, "check out");
182	        }
183	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
184	        store.update(reservation);
185	        return new ReservationReceipt(reservation, roomOf(reservation));
186	    }
187	
188	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
189	    public ReservationReceipt receiptCopy(long reservationId) {
190	        Reservation reservation = find(reservationId);
191	        if (!reservation.isPaid()) {
192	            throw notAllowed(reservation, "issue a receipt for");
193	        }
194	        return new ReservationReceipt(reservation, roomOf(reservation));
195	    }
196	
197	    private Room roomOf(Reservation reservation) {
198	        return rooms.find(reservation.roomNumber()).orElseThrow();
199	    }
200	
201	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
202	        return "Olá, " + reservation.guest().name() + "!\n\n"
203	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
204	                + receipt.text() + "\n"
205	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
206	                + "Até breve!\n";
207	    }
208	
209	    private static HotelException notAllowed(Reservation reservation, String operation) {
210	        return new HotelException(
211	                ErrorCode.OPERATION_NOT_ALLOWED,
212	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
213	    }
214	}
215	package hotel;
216	
217	import hotel.messages.EmailSender;
218	import hotel.messages.SentMessages;
219	import hotel.reports.OccupancyReport;
220	import hotel.reports.RevenueReport;
221	import hotel.reservations.PriceCalculator;
222	import hotel.reservations.ReservationService;
223	import hotel.reservations.ReservationStore;
224	import hotel.rooms.Rooms;
225	import hotel.web.HttpApi;
226	import io.javalin.Javalin;
227	import javax.sql.DataSource;
228	
229	/** Puts the inn's pieces together and runs the HTTP server. */
230	public final class Hotel {
231	
232	    private final Javalin server;
233	
234	    public Hotel(DataSource dataSource) {
235	        Rooms rooms = new Rooms(dataSource);
236	        ReservationStore store = new ReservationStore(dataSource);
237	        SentMessages sentMessages = new SentMessages(dataSource);
238	        ReservationService reservations =
239	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
240	        HttpApi api = new HttpApi(
241	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
242	        this.server = api.server();
243	    }
244	
245	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
246	    public int start(int port) {
247	        server.start(port);
248	        return server.port();
249	    }
250	
251	    public void stop() {
252	        server.stop();
253	    }
254	
255	    public static void main(String[] args) {
256	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
257	        Database database = new Database(System.getenv());
258	        new Hotel(database.dataSource()).start(port);
259	    }
260	}

