288	import hotel.rooms.Room;
289	import java.math.BigDecimal;
290	import java.math.RoundingMode;
291	import java.time.LocalDate;
292	import java.time.Month;
293	
294	/**
295	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
296	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
297	 * (half-even) at every step.
298	 */
299	public final class PriceCalculator {
300	
301	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
302	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
303	
304	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
305	        int nights = 0;
306	        BigDecimal subtotal = cents(BigDecimal.ZERO);
307	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
308	            subtotal = subtotal.add(nightPrice(room, night));
309	            nights++;
310	        }
311	        BigDecimal discount = switch (ratePlan) {
312	            case STANDARD -> cents(BigDecimal.ZERO);
313	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
314	        };
315	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
316	    }
317	
318	    BigDecimal nightPrice(Room room, LocalDate night) {
319	        BigDecimal nightlyRate = room.nightlyRate();
320	        if (isHighSeason(night)) {
321	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
322	        }
323	        return cents(nightlyRate);
324	    }
325	
326	    /** High season: from December 15 to the end of February, and the whole of July. */
327	    static boolean isHighSeason(LocalDate date) {
328	        Month month = date.getMonth();
329	        return month == Month.JANUARY
330	                || month == Month.FEBRUARY
331	                || month == Month.JULY
332	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
333	    }
334	
335	    static BigDecimal cents(BigDecimal value) {
336	        return value.setScale(2, RoundingMode.HALF_EVEN);
337	    }
338	}
